/**
 * components/ui/alert-dialog.tsx
 *
 * Confirmation dialog — focus-trapped, scroll-lock safe.
 */
import { effect, onCleanup, signal } from '@vorzelajs/core'
import { Show } from '@vorzelajs/dom'
import { accessorOf } from '~/hooks/index.ts'
import { useId } from '~/hooks/use-id.ts'
import { cx } from '~/lib/cx.ts'
import { lockBodyScroll, trapFocus } from '~/lib/overlay.ts'
import type { ReactNode } from '~/lib/types.ts'
import { Portal } from '~/components/primitives/portal.tsx'
import { Button } from './button.tsx'
import styles from './alert-dialog.module.scss'

export interface AlertDialogProps {
  open: boolean | (() => boolean)
  onOpenChange: (open: boolean) => void
  title?: string
  description?: string
  cancelText?: string
  actionText?: string
  onAction?: () => void
  onCancel?: () => void
  destructive?: boolean
  className?: string
  children?: ReactNode
}

export function AlertDialog({
  open,
  onOpenChange,
  title,
  description,
  cancelText = 'Cancel',
  actionText = 'Continue',
  onAction,
  onCancel,
  destructive = false,
  className,
  children,
}: AlertDialogProps) {
  const titleId = useId('alert-dialog-title')
  const descId = useId('alert-dialog-description')
  const [panel, setPanel] = signal<HTMLDivElement | null>(null)
  const isOpen = accessorOf(open)

  effect(() => {
    const node = panel()
    if (!isOpen() || !node || typeof document === 'undefined') return
    const unlock = lockBodyScroll()
    const releaseTrap = trapFocus(node, () => onOpenChange(false))
    onCleanup(() => {
      releaseTrap()
      unlock()
    })
  })

  const handleCancel = (): void => {
    onCancel?.()
    onOpenChange(false)
  }

  const handleAction = (): void => {
    onAction?.()
  }

  return (
    <Show when={isOpen}>
      {() => {
        const content = (
          <Portal>
            <div className={styles.root}>
              <div
                className={styles.overlay}
                aria-hidden="true"
                onClick={handleCancel}
              />

              <div
                ref={(element) => setPanel(element as HTMLDivElement)}
                role="alertdialog"
                aria-modal="true"
                aria-labelledby={title ? titleId : undefined}
                aria-describedby={description ? descId : undefined}
                tabIndex={-1}
                className={cx(styles.panel, className)}
                onClick={(event) => event.stopPropagation()}
              >
                <div className={styles.content}>
                  {title ? (
                    <h2 id={titleId} className={styles.title}>
                      {title}
                    </h2>
                  ) : null}

                  {description ? (
                    <p id={descId} className={styles.description}>
                      {description}
                    </p>
                  ) : null}

                  {children}
                </div>

                <div className={styles.actions}>
                  <Button variant="outline" onClick={handleCancel}>
                    {cancelText}
                  </Button>
                  <Button
                    variant={destructive ? 'destructive' : 'primary'}
                    onClick={handleAction}
                  >
                    {actionText}
                  </Button>
                </div>
              </div>
            </div>
          </Portal>
        )

        onCleanup(() => setPanel(null))
        return content
      }}
    </Show>
  )
}

export { AlertDialog as ConfirmationDialog }

@use 'styles' as vz;

.root {
  position: fixed;
  inset: 0;
  z-index: vz.z('modal');
  display: flex;
  align-items: center;
  justify-content: center;
  padding: vz.space(4);
}

.overlay {
  position: absolute;
  inset: 0;

  @include vz.scrim(12px);

  animation: vz-alert-dialog-overlay-in vz.duration('base') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.panel {
  position: relative;
  width: 100%;
  max-width: 28rem;
  border: 1px solid vz.color('border', 0.8);
  border-radius: vz.radius('2xl');
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(3);
  outline: none;
  animation: vz-alert-dialog-in vz.duration('slow') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.content {
  display: flex;
  flex-direction: column;
  gap: vz.space(2);
  padding: vz.space(6) vz.space(6) 0;
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('lg');
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  line-height: 1.5;
}

.actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: vz.space(2);
  padding: vz.space(4) vz.space(6);
}

@keyframes vz-alert-dialog-overlay-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes vz-alert-dialog-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: none;
  }
}
